import java.util.List;

/** A sheet's audit lines, exactly as the audit file holds them, newest first. */
public record AuditLinesResponse(List<String> lines) {
}
package net.officefloor.hq.app.audit;

import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The audit viewer: the sheet's lines read from the audit file (it is not a second record), newest
 * first. With a name in {@code ?name=} only the lines carrying {@code name=} or {@code person=} that
 * name, compared as names are compared (case and surrounding spaces ignored), followed by the
 * matching lines of the sheet's descendants (each sheet's newest first, the sheets in id order). When that name is a
 * person on the sheet transferred from another sheet, the lines about them from the sheet they came
 * from follow, newest first, as that sheet's file holds them.
 */
public class RespondWithAuditLines {
    public void respond(@Val Sheet sheet, Audit audit, PersonRepository people, SheetRepository sheets,
            HttpServletRequest request,
            ObjectResponse<AuditLinesResponse> response) {
        String name = request.getParameter("name");
        name = name == null ? "" : name;
        List<String> lines = new ArrayList<>(audit.linesFor(sheet.id(), name));
        Collections.reverse(lines);
        if (!name.isBlank()) {
            for (String descendant : sheets.descendants(sheet.id())) {
                List<String> below = new ArrayList<>(audit.linesFor(descendant, name));
                Collections.reverse(below);
                lines.addAll(below);
            }
            Person person = people.findByName(sheet.id(), name);
            if (person != null && person.getOriginSheet() != null) {
                List<String> origin = new ArrayList<>(audit.linesFor(person.getOriginSheet(), person.getName()));
                Collections.reverse(origin);
                lines.addAll(origin);
            }
        }
        response.send(new AuditLinesResponse(lines));
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';

// The audit viewer: a filter entry, a show button and the sheet's audit lines, read from the audit
// file exactly as it holds them, newest first. A name in the filter keeps only the lines about that
// person (name= or person= that name, case and surrounding spaces ignored), then the matching lines of
// the sheet's descendants (each sheet newest first, the sheets by id), followed, for someone
// transferred here, by the lines about them from the sheet they came from. It writes nothing.
function AuditViewer({ sheetId }: { sheetId: string }) {
  const [user] = useUser();
  const [filter, setFilter] = useState('');
  const [lines, setLines] = useState<string[]>([]);
  const [error, setError] = useState('');

  const show = useMutation({
    mutationFn: (name: string) =>
      getJson<{ lines: string[] }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/audit?name=${encodeURIComponent(name)}`,
        user,
      ),
    onSuccess: (data) => setLines(data.lines),
    onError: () => setError('The audit could not be read.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLines([]);
    show.mutate(filter);
  };

  return (
    <section data-testid="audit-viewer">
      <h2>Audit</h2>
      <form onSubmit={submit}>
        <label>
          Person{' '}
          <input
            data-testid="audit-filter"
            value={filter}
            onChange={(e) => {
              setFilter(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="audit-show" disabled={show.isPending}>
          Show
        </button>
        {error && (
          <p role="alert" data-testid="audit-error">
            {error}
          </p>
        )}
      </form>
      <ul data-testid="audit-lines">
        {lines.map((line, i) => (
          <li key={i} data-testid="audit-line">
            {line}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 40, Component: AuditViewer });
