                ))}
              </ol>
              <ol data-testid="claim-comments">
                {c.comments.map((line, i) => (
                  <li key={i} data-testid="claim-comments-line">
                    {line}
                  </li>
                ))}
              </ol>
              <ol data-testid="claim-log">
                {c.log.map((line, i) => (
                  <li key={i} data-testid="claim-log-line">
                    {line}
                  </li>
                ))}
              </ol>
              {refused?.id === c.id && (
                <p role="alert" data-testid="claim-error">
                  {refused.message}
                </p>
              )}
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}

